window.VSTEP_DATA = {"listening":[{"part":1,"first":1,"last":1,"title":"Clinic appointment change","audio":"P1.1.mp3","script":[{"speaker":"Female announcer","text":"Good morning. This is a message from the Riverside Health Centre for patients with appointments on Thursday. Dr Lewis will be attending a training course, so appointments originally booked for Thursday morning have been moved to Friday afternoon. The clinic will contact each patient with an exact time. Please do not arrive on Thursday unless a nurse has specifically asked you to come in. If your symptoms become worse before your new appointment, call the clinic for advice. The telephone number on your appointment card has not changed."}],"questions":[{"n":1,"stem":"Why is the health centre changing some appointments?","options":{"A":"A new nurse has joined the clinic.","B":"A doctor will be away for training.","C":"The centre has closed for repairs.","D":"Patients requested longer appointments."},"answer":"B","evidence":"Dr Lewis will be attending a training course","explanation_en":"The schedule changes because Dr Lewis is away for training, not because of repairs or patient requests.","explanation":"Lịch hẹn thay đổi vì bác sĩ Lewis tham dự khóa tập huấn; những phương án còn lại không phải nguyên nhân được nêu."}]},{"part":1,"first":2,"last":2,"title":"Community vaccination day","audio":"P1.2.mp3","script":[{"speaker":"Male announcer","text":"Attention, residents. Our community vaccination day will take place this Saturday at the Eastside Community Hall, not at the hospital as stated on the old posters. Those who have already made an appointment should bring their confirmation message and any relevant medical information. Walk-in visitors may be accepted later in the afternoon, depending on available appointments. If you have a history of serious allergies, tell the health worker before your vaccination. The event begins at nine, and the information desk opens half an hour earlier."}],"questions":[{"n":2,"stem":"Where will the vaccination event be held?","options":{"A":"At Eastside Community Hall","B":"At the main hospital","C":"At the public library","D":"At the old sports centre"},"answer":"A","evidence":"will take place this Saturday at the Eastside Community Hall, not at the hospital","explanation_en":"The speaker corrects the old poster: the community hall is the current venue; the hospital is the former location.","explanation":"Người nói đính chính địa điểm cũ trên áp phích: buổi tiêm chủng diễn ra tại nhà sinh hoạt cộng đồng, không phải bệnh viện."}]},{"part":1,"first":3,"last":3,"title":"New exercise class arrangements","audio":"P1.3.mp3","script":[{"speaker":"Female instructor","text":"Hello, everyone. Due to the unusually hot weather, tomorrow's outdoor fitness session will not take place in the park. Instead, we will meet in the air-conditioned activity room on the ground floor of the sports centre. The time is unchanged: six thirty in the evening. We will focus on gentle movement and stretching rather than intensive running. Please wear comfortable clothes, bring water so that you can stay hydrated, and let the instructor know if you are recovering from an injury."}],"questions":[{"n":3,"stem":"What will participants do differently tomorrow?","options":{"A":"Run longer distances outdoors","B":"Start an hour earlier","C":"Meet indoors for gentler exercise","D":"Cancel their exercise session altogether"},"answer":"C","evidence":"we will meet in the air-conditioned activity room on the ground floor of the sports centre","explanation_en":"The class moves indoors and focuses on gentle movement. The starting time remains the same.","explanation":"Lớp chuyển vào phòng trong nhà và tập nhẹ nhàng; giờ bắt đầu không thay đổi."}]},{"part":1,"first":4,"last":4,"title":"Prescription collection notice","audio":"P1.4.mp3","script":[{"speaker":"Male pharmacist","text":"This is a reminder from the Oak Street Pharmacy. Patients collecting repeat prescriptions should use the new service counter at the back of the shop from Monday. Please bring your prescription number, either on paper or on your phone. You do not need to wait in the general queue unless you also wish to buy other products. Our pharmacist can discuss possible side effects, but changes to the amount of medicine you take must be agreed with your doctor. The pharmacy's opening hours will remain the same."}],"questions":[{"n":4,"stem":"What should patients bring when collecting a repeat prescription?","options":{"A":"Their full medical history","B":"A hospital discharge letter","C":"A receipt from the previous visit","D":"Their prescription number"},"answer":"D","evidence":"Please bring your prescription number, either on paper or on your phone.","explanation_en":"The required item is the prescription number, which may be shown on paper or a phone.","explanation":"Người bệnh cần mang mã số đơn thuốc, bản giấy hoặc trên điện thoại; không yêu cầu ba loại giấy tờ còn lại."}]},{"part":1,"first":5,"last":5,"title":"University mental health workshop","audio":"P1.5.mp3","script":[{"speaker":"Female organiser","text":"A short announcement for university students. The workshop on stress and emotional well-being has been moved from Tuesday to Wednesday because the counsellor is unavailable on the original date. It will still take place in Room 204 of the Student Support Building and will begin at two o'clock. During the session, students will discuss simple ways to manage exam pressure and improve sleep habits. Places are limited, so anyone who registered but can no longer attend should cancel through the university portal by Monday evening."}],"questions":[{"n":5,"stem":"What has changed about the mental health workshop?","options":{"A":"The date","B":"The room","C":"The starting time","D":"The topic"},"answer":"A","evidence":"has been moved from Tuesday to Wednesday","explanation_en":"Only the day changes from Tuesday to Wednesday; the room, time and subject stay the same.","explanation":"Chỉ thay đổi ngày tổ chức từ thứ Ba sang thứ Tư; phòng, giờ và chủ đề vẫn giữ nguyên."}]},{"part":1,"first":6,"last":6,"title":"Hospital visitor information","audio":"P1.6.mp3","script":[{"speaker":"Male receptionist","text":"Visitors to the Westbrook Hospital are reminded that a seasonal flu outbreak has affected one of our wards. As a preventive measure, visitors to that ward must speak to the reception nurse before entering. Visiting hours elsewhere in the hospital have not changed. Please follow signs at the entrance, use the hand-cleaning stations, and postpone your visit if you have a fever or other flu symptoms. These precautions are intended to help protect patients whose immune systems may be weak."}],"questions":[{"n":6,"stem":"Why must some visitors speak to a nurse first?","options":{"A":"All hospital wards are closed.","B":"A flu outbreak has affected one ward.","C":"The hospital has changed its visiting hours.","D":"Patients are moving to a new building."},"answer":"B","evidence":"a seasonal flu outbreak has affected one of our wards","explanation_en":"The extra check applies to the affected ward because of a flu outbreak, not to every hospital visitor.","explanation":"Quy định gặp y tá chỉ áp dụng với khu điều trị có đợt bùng phát cúm; các khu khác không đổi giờ thăm."}]},{"part":1,"first":7,"last":7,"title":"Health screening programme","audio":"P1.7.mp3","script":[{"speaker":"Female announcer","text":"Good afternoon. Employees who have booked a workplace health check-up next week should arrive ten minutes before their scheduled time. The nurse will check blood pressure and ask a few questions about lifestyle and existing health conditions. The check-up will take place in the training room on the second floor. Please note that this is a basic screening, not a full medical examination. Anyone needing further tests will be advised to make an appointment with a doctor. You may return to work immediately afterward."}],"questions":[{"n":7,"stem":"What is the main purpose of the announcement?","options":{"A":"To ask employees to cancel their appointments","B":"To introduce a new treatment for high blood pressure","C":"To explain arrangements for a basic workplace check-up","D":"To invite staff to attend a sports competition"},"answer":"C","evidence":"Employees who have booked a workplace health check-up next week should arrive ten minutes before their scheduled time.","explanation_en":"The message explains arrival time, place and scope of a basic health screening.","explanation":"Thông báo hướng dẫn thời điểm đến, địa điểm và nội dung khám sàng lọc sức khỏe cơ bản."}]},{"part":1,"first":8,"last":8,"title":"Rehabilitation class cancellation","audio":"P1.8.mp3","script":[{"speaker":"Male coordinator","text":"This is a message for members of the Tuesday rehabilitation class. The physiotherapist is ill, so the usual group session will not take place tomorrow. Please do not replace it with a more demanding workout on your own. You may continue the gentle exercises already approved in your individual recovery plan, if you feel comfortable doing so. The next supervised session is scheduled for Thursday at four o'clock, and staff will contact anyone whose treatment plan needs to be adjusted."}],"questions":[{"n":8,"stem":"What are class members advised to do tomorrow?","options":{"A":"Begin a more intensive exercise programme","B":"Attend the usual class at a different venue","C":"Stop all activity until next month","D":"Follow only previously approved gentle exercises if comfortable"},"answer":"D","evidence":"You may continue the gentle exercises already approved in your individual recovery plan, if you feel comfortable doing so.","explanation_en":"The supervised session is cancelled; members may do only the gentle exercises already approved for them.","explanation":"Buổi tập có hướng dẫn bị hủy; học viên chỉ nên thực hiện bài tập nhẹ đã được phê duyệt trong kế hoạch phục hồi nếu cảm thấy phù hợp."}]},{"part":2,"first":9,"last":12,"title":"Conversation 1 – A clinic appointment and persistent symptoms","audio":"P2.1.mp3","script":[{"speaker":"Speaker 1 (Male)","text":"Good morning. I'd like to make an appointment, but I'm not sure whether I need to see a doctor today. I've had a headache and a mild fever since yesterday."},{"speaker":"Speaker 2 (Female)","text":"I'm sorry you're feeling unwell. I'm the receptionist, so I can't give you a diagnosis, but I can arrange for a nurse to assess your symptoms. Do you have any difficulty breathing or other symptoms that worry you?"},{"speaker":"Speaker 1 (Male)","text":"No breathing problems. I did come down with the flu last month, and this feels similar. I took a day off work because I couldn't concentrate."},{"speaker":"Speaker 2 (Female)","text":"Thank you for explaining. We have a nurse-led assessment at eleven forty today. The doctor has no routine appointments left this morning, but the nurse can decide whether an earlier medical review is necessary."},{"speaker":"Speaker 1 (Male)","text":"I thought the website showed an appointment at ten thirty. Has that already been taken?"},{"speaker":"Speaker 2 (Female)","text":"That time is reserved for a vaccination follow-up, so it isn't available for a new consultation. Would you like the eleven-forty assessment?"},{"speaker":"Speaker 1 (Male)","text":"Yes, please. Should I bring the medicine I used last month?"},{"speaker":"Speaker 2 (Female)","text":"A list of medicines and any allergies would be helpful. You can also tell the nurse whether your symptoms have been getting better or worse. If you become seriously unwell before the appointment, seek urgent medical advice rather than waiting."},{"speaker":"Speaker 1 (Male)","text":"Understood. So I should check in at reception before eleven forty and explain my symptoms to the nurse first."},{"speaker":"Speaker 2 (Female)","text":"Exactly. I'll send you a confirmation message now. We hope you feel better soon."}],"questions":[{"n":9,"stem":"Why does the man contact the clinic?","options":{"A":"He needs to change a vaccination appointment.","B":"He wants advice about a persistent headache and fever.","C":"He is asking for a medical certificate for a relative.","D":"He wants to collect a prescription."},"answer":"B","evidence":"I've had a headache and a mild fever since yesterday.","explanation_en":"He is unwell and wants an appointment or assessment; he is not seeking a vaccination or prescription collection.","explanation":"Người nam liên hệ vì bị đau đầu và sốt nhẹ từ hôm trước; anh muốn được đánh giá triệu chứng, không phải đến tiêm chủng hay lấy thuốc."},{"n":10,"stem":"Which type of appointment can the man book today?","options":{"A":"A routine consultation with a doctor","B":"A specialist examination","C":"A nurse-led symptom assessment","D":"A vaccination follow-up appointment"},"answer":"C","evidence":"We have a nurse-led assessment at eleven forty today.","explanation_en":"The receptionist offers a nurse-led assessment at 11:40. The doctor has no routine appointments left, and the 10:30 vaccination follow-up slot is reserved.","explanation":"Nhân viên lễ tân đề nghị buổi đánh giá triệu chứng do y tá thực hiện lúc 11:40. Bác sĩ đã hết lịch khám thông thường trong buổi sáng; lịch theo dõi sau tiêm lúc 10:30 được dành riêng."},{"n":11,"stem":"Why can the man not book the 10:30 slot?","options":{"A":"It is reserved for a vaccination follow-up.","B":"The doctor has moved the appointment to another clinic.","C":"The clinic is closed until noon.","D":"He has not registered on the website."},"answer":"A","evidence":"That time is reserved for a vaccination follow-up","explanation_en":"The woman clearly identifies the 10:30 appointment as reserved for a different service.","explanation":"Người nữ xác nhận lịch 10:30 đã dành riêng cho trường hợp theo dõi sau tiêm, không phải vì phòng khám đóng cửa hay thiếu đăng ký."},{"n":12,"stem":"Which item does the woman recommend bringing?","options":{"A":"A signed letter from his employer","B":"A receipt from his last vaccination","C":"A copy of his university timetable","D":"A list of medicines and known allergies"},"answer":"D","evidence":"A list of medicines and any allergies would be helpful.","explanation_en":"She asks him to bring information about medicines and allergies so the nurse can assess his condition.","explanation":"Người nữ khuyên mang danh sách thuốc đã dùng và tình trạng dị ứng để hỗ trợ y tá đánh giá."}]},{"part":2,"first":13,"last":16,"title":"Conversation 2 – Exercise, stress and a realistic routine","audio":"P2.2.mp3","script":[{"speaker":"Speaker 1 (Male)","text":"Hi, I'm Minh. I've signed up for the university well-being programme because I sit at a desk most of the day. I know a sedentary lifestyle isn't healthy, but I can't imagine spending an hour in the gym every evening."},{"speaker":"Speaker 2 (Female)","text":"You don't need to begin with an hour. I'm the programme coach, and our first goal is to establish a routine you can actually maintain. What does a normal weekday look like for you?"},{"speaker":"Speaker 1 (Male)","text":"I take the bus to campus, sit through lectures, then work online until late. I often skip lunch and drink coffee to stay awake. During exams, I suffer from stress and struggle to get enough sleep."},{"speaker":"Speaker 2 (Female)","text":"Then let's focus on small changes. Could you walk for fifteen minutes after lunch on most days? You could also stand up and stretch between study sessions."},{"speaker":"Speaker 1 (Male)","text":"That sounds manageable. But shouldn't I push myself harder if I want to improve quickly?"},{"speaker":"Speaker 2 (Female)","text":"Not necessarily. If you change everything at once, you may give up. Gradual changes are easier to sustain. Think about a balanced diet, regular movement and more consistent sleep, not just intense exercise."},{"speaker":"Speaker 1 (Male)","text":"I have a knee injury from football, so running still feels uncomfortable. Would walking be a problem?"},{"speaker":"Speaker 2 (Female)","text":"You should follow medical advice about the injury. We can adapt the programme, but I won't recommend activities that go against your treatment or rehabilitation plan."},{"speaker":"Speaker 1 (Male)","text":"Fair enough. Could I keep a record of my activity and show it to you next week?"},{"speaker":"Speaker 2 (Female)","text":"Yes. Note what you tried and how you felt. We'll review the record together and make realistic adjustments rather than judging you by a fixed target."}],"questions":[{"n":13,"stem":"What is the man’s main difficulty?","options":{"A":"He cannot afford a health club membership.","B":"He has never heard of regular exercise.","C":"He has no access to healthy food.","D":"He spends long periods sitting and struggles to maintain healthy habits."},"answer":"D","evidence":"I sit at a desk most of the day. I know a sedentary lifestyle isn't healthy","explanation_en":"His long sitting hours, irregular meals and poor sleep are the issue; the coach plans sustainable changes.","explanation":"Khó khăn chính là thói quen ngồi lâu và sinh hoạt thiếu điều độ; người nữ đề xuất thay đổi bền vững chứ không tập quá sức."},{"n":14,"stem":"What does the coach suggest as a starting point?","options":{"A":"Walking briefly after lunch and stretching between study sessions","B":"Cycling to campus several mornings a week","C":"Swimming twice a week at the university pool","D":"Joining a gentle yoga class on alternate evenings"},"answer":"A","evidence":"Could you walk for fifteen minutes after lunch on most days? You could also stand up and stretch between study sessions.","explanation_en":"The coach specifically suggests a fifteen-minute walk after lunch and stretching during study breaks. The other options are plausible activities, but none is proposed in the recording.","explanation":"Huấn luyện viên nêu cụ thể việc đi bộ khoảng 15 phút sau bữa trưa và đứng dậy giãn cơ giữa các buổi học. Những hoạt động khác nghe có vẻ hợp lý nhưng không được đề xuất trong hội thoại."},{"n":15,"stem":"Why does the coach discourage changing everything immediately?","options":{"A":"The university programme has already ended.","B":"Rapid changes may cause him to abandon the routine.","C":"He must buy new exercise equipment first.","D":"His lectures will become longer next month."},"answer":"B","evidence":"If you change everything at once, you may give up.","explanation_en":"The coach argues that gradual change is more sustainable because overly ambitious plans may be abandoned.","explanation":"Người nữ nói nếu thay đổi tất cả ngay lập tức, anh có thể bỏ cuộc; tiến độ từ từ dễ duy trì hơn."},{"n":16,"stem":"What can be inferred about the coach’s approach?","options":{"A":"She uses the same fixed target for all students.","B":"She believes exercise should replace medical treatment.","C":"She adjusts advice to the student’s circumstances and health needs.","D":"She focuses only on weight loss."},"answer":"C","evidence":"We'll review the record together and make realistic adjustments rather than judging you by a fixed target.","explanation_en":"The coach considers his schedule, injury and recorded progress, showing an individualised approach.","explanation":"Huấn luyện viên xem xét lịch học, chấn thương và nhật ký theo dõi để điều chỉnh mục tiêu, không áp dụng chỉ tiêu cứng cho mọi người."}]},{"part":2,"first":17,"last":20,"title":"Conversation 3 – Recovery after an operation","audio":"P2.3.mp3","script":[{"speaker":"Speaker 1 (Male)","text":"Good afternoon. I've come for my follow-up appointment after knee surgery. The operation went well, but recovery is slower than I expected."},{"speaker":"Speaker 2 (Female)","text":"I'm Dr Park's rehabilitation nurse. A gradual recovery is common, and your recent notes show that the swelling has decreased. How are you managing the exercises at home?"},{"speaker":"Speaker 1 (Male)","text":"I do the gentle movements each morning. The painkillers help, although their effect seems to wear off before bedtime. I'm worried that I might be doing something wrong."},{"speaker":"Speaker 2 (Female)","text":"You should mention that to the doctor before making any change to the medicine. We can monitor your condition, but only the prescribing clinician should advise you on your dose."},{"speaker":"Speaker 1 (Male)","text":"Understood. My neighbour told me to begin jogging so the leg would get strong again. Is that a good idea?"},{"speaker":"Speaker 2 (Female)","text":"Not yet. Jogging isn't part of your approved rehabilitation plan. Your next step is to practise walking for short periods and gradually improve movement, following the physiotherapist's instructions."},{"speaker":"Speaker 1 (Male)","text":"I also want to return to my job at the bookstore. I stand for several hours there."},{"speaker":"Speaker 2 (Female)","text":"That is useful to know. Rather than returning to a full shift immediately, discuss a gradual return with your employer and medical team. The plan may include shorter shifts at first."},{"speaker":"Speaker 1 (Male)","text":"So the aim isn't to get back to normal as quickly as possible?"},{"speaker":"Speaker 2 (Female)","text":"Exactly. The priority is steady progress without putting unnecessary pressure on the injured knee. Your next review is in two weeks, when we can assess whether the plan needs to change."}],"questions":[{"n":17,"stem":"What improvement does the nurse mention?","options":{"A":"The man has already returned to his job.","B":"His swelling has decreased.","C":"His knee no longer needs exercise.","D":"He has stopped using painkillers."},"answer":"B","evidence":"your recent notes show that the swelling has decreased.","explanation_en":"The nurse notes reduced swelling, while other aspects of recovery remain ongoing.","explanation":"Y tá cho biết tình trạng sưng đã giảm; không nói bệnh nhân đã đi làm lại hay hết cần tập phục hồi."},{"n":18,"stem":"What does the nurse say about changing pain medication?","options":{"A":"He can double the dose before bed.","B":"His neighbour may recommend a new medicine.","C":"Only the physiotherapist should change the dose.","D":"He should discuss it with the prescribing doctor first."},"answer":"D","evidence":"only the prescribing clinician should advise you on your dose.","explanation_en":"The nurse explicitly says dosage decisions belong to the prescribing clinician.","explanation":"Y tá nhấn mạnh việc điều chỉnh liều thuốc cần do người kê đơn hướng dẫn, không do bệnh nhân tự thay đổi."},{"n":19,"stem":"Why does the nurse advise against jogging at present?","options":{"A":"It is not part of his approved rehabilitation plan.","B":"It would prevent him from sleeping at night.","C":"The bookstore has no place for exercise.","D":"His follow-up appointment has been cancelled."},"answer":"A","evidence":"Jogging isn't part of your approved rehabilitation plan.","explanation_en":"Jogging is not approved yet; short walks and gradual movement are currently recommended.","explanation":"Chạy bộ chưa nằm trong kế hoạch phục hồi được cho phép; hiện tại chỉ nên đi bộ ngắn và vận động tăng dần."},{"n":20,"stem":"What is the main message of the conversation?","options":{"A":"Recovery should be judged by how quickly someone returns to sport.","B":"Pain medication should always be avoided after an operation.","C":"A safe, gradual return to normal activities matters more than speed.","D":"People with knee injuries should never return to standing jobs."},"answer":"C","evidence":"The priority is steady progress without putting unnecessary pressure on the injured knee.","explanation_en":"Both the rehabilitation and work-return advice prioritise gradual, safe recovery over speed.","explanation":"Cả việc phục hồi và quay lại công việc đều cần tiến hành từ từ, an toàn; không chạy theo tốc độ hồi phục."}]},{"part":3,"first":21,"last":25,"title":"Talk 1 – Preventing infections in shared spaces","audio":"P3.1.mp3","script":[{"speaker":"Female lecturer","text":"Good afternoon. Today we will look at how communities can reduce the spread of common infections. Effective prevention depends on practical habits and clear information."},{"speaker":"Lecturer","text":"Some respiratory viruses spread through close contact. People with symptoms should follow public health advice and avoid unnecessary contact. Hand hygiene and cleaning shared surfaces can also help. No single measure removes every risk, so prevention usually involves several actions working together."},{"speaker":"Lecturer","text":"Vaccination programmes may reduce the impact of certain diseases, but individual circumstances matter. At a vaccination appointment, discuss known allergies or previous reactions with a qualified health professional. Advice for one person may not suit another."},{"speaker":"Clear messages are also important. During one local outbreak, posters outside a school confused some students","text":"several students misunderstood the message and believed the entire campus was closed. In fact, only one activity had been temporarily suspended. A follow-up announcement explained the difference."},{"speaker":"Lecturer","text":"Finally, precautions should protect vulnerable people, including patients with weakened immune systems. Extra rules for visitors aim to reduce risks, not blame anyone. Accurate information can prevent unnecessary panic and support practical decisions. Consistent habits and cooperation matter more than dramatic announcements."}],"questions":[{"n":21,"stem":"What is the main focus of the talk?","options":{"A":"The cost of developing new hospital buildings","B":"The advantages of replacing all medicines with exercise","C":"Practical community measures for limiting infections","D":"The history of infectious diseases"},"answer":"C","evidence":"communities can reduce the spread of common infections","explanation_en":"The lecturer discusses prevention through hygiene, vaccination guidance and clear communication.","explanation":"Bài nói tập trung vào cách cộng đồng hạn chế lây lan bệnh bằng vệ sinh, hướng dẫn tiêm chủng và truyền thông chính xác."},{"n":22,"stem":"Why does the speaker recommend combining preventive measures?","options":{"A":"To show that no single action can remove all risks","B":"To suggest that vaccination is always unnecessary","C":"To argue that hand hygiene has no value","D":"To recommend closing every shared space immediately"},"answer":"A","evidence":"No single measure removes every risk, so prevention usually involves several actions working together.","explanation_en":"The lecturer emphasises combining measures rather than relying on one solution.","explanation":"Người nói giải thích không biện pháp đơn lẻ nào loại bỏ mọi nguy cơ; cần phối hợp nhiều cách phòng ngừa."},{"n":23,"stem":"What should people mention at a vaccination appointment?","options":{"A":"Their preferred holiday destinations","B":"Their previous examination grades","C":"The names of all school teachers","D":"Relevant allergies or earlier reactions"},"answer":"D","evidence":"discuss known allergies or previous reactions with a qualified health professional.","explanation_en":"The talk stresses sharing relevant allergy and reaction history with a professional.","explanation":"Người đi tiêm nên trao đổi về dị ứng hoặc phản ứng từng gặp với nhân viên y tế đủ chuyên môn."},{"n":24,"stem":"What did some students misunderstand after reading the school notice?","options":{"A":"The school had no information desk.","B":"Some students misunderstood the extent of a temporary closure.","C":"Several teachers refused to attend classes.","D":"The community ran out of vaccination appointments."},"answer":"B","evidence":"several students misunderstood the message and believed the entire campus was closed.","explanation_en":"The communication was misunderstood: only one activity, not the whole campus, was suspended.","explanation":"Một số sinh viên hiểu nhầm rằng toàn bộ trường đóng cửa trong khi chỉ một hoạt động tạm dừng."},{"n":25,"stem":"What can be inferred about the lecturer’s view of public health communication?","options":{"A":"It should include complex medical terms whenever possible.","B":"It matters less than making dramatic announcements.","C":"It needs to be accurate, clear and considerate of vulnerable people.","D":"It should avoid mentioning uncertainty under all circumstances."},"answer":"C","evidence":"Accurate information can prevent unnecessary panic and support practical decisions.","explanation_en":"The lecturer values clarity and accuracy as part of effective, considerate prevention.","explanation":"Người nói đề cao thông tin chính xác, dễ hiểu để tránh hoang mang và giúp mọi người ra quyết định phù hợp."}]},{"part":3,"first":26,"last":30,"title":"Talk 2 – Student well-being and the sedentary lifestyle","audio":"P3.2.mp3","script":[{"speaker":"Male lecturer","text":"Welcome to this session on student well-being. University life involves long hours at desks and screens, sometimes creating a sedentary lifestyle. Daily habits and appropriate support matter more than a perfect plan."},{"speaker":"Lecturer","text":"Movement need not involve competitive sport or a gym. Walking between buildings, taking the stairs when appropriate or stretching during study breaks can help. Choose a realistic, safe routine. Anyone recovering from an injury should follow medical advice."},{"speaker":"Lecturer","text":"Sleep, food and stress also influence well-being. A balanced diet supports energy, while enough sleep helps concentration. During exams, some students stay awake late and skip meals to save time. However, this approach can make it harder to study effectively."},{"speaker":"Lecturer","text":"Students who suffer from stress sometimes avoid asking for help because they fear being judged. Universities can offer confidential counselling and remind students that seeking support is a responsible decision, not a weakness. Healthy habits cannot replace necessary professional treatment."},{"speaker":"Lecturer","text":"Recently, a student group reminded members to take short walking breaks between study sessions. They said the plan was easier to continue than a demanding programme they had attempted before. That does not mean one method suits everyone. In short, a healthier student life depends on steady habits, not a perfect timetable."}],"questions":[{"n":26,"stem":"What is the main message of the talk about student well-being?","options":{"A":"Student health is influenced by practical daily habits and support.","B":"University students should stop using all digital devices.","C":"Only professional athletes benefit from physical activity.","D":"Examination results depend entirely on sleep."},"answer":"A","evidence":"a healthier student life depends on steady habits, not a perfect timetable.","explanation_en":"The talk connects movement, sleep, diet, stress support and sustainable routines.","explanation":"Bài nói cho rằng sức khỏe sinh viên phụ thuộc vào thói quen đều đặn và hỗ trợ phù hợp, không chỉ một yếu tố."},{"n":27,"stem":"Which activity is mentioned as a realistic way to move more?","options":{"A":"Joining a competitive sports team immediately","B":"Replacing all lectures with online learning","C":"Taking short walking or stretching breaks","D":"Exercising intensively for several hours every night"},"answer":"C","evidence":"Walking between buildings, taking the stairs when appropriate or stretching during study breaks","explanation_en":"The speaker suggests modest activity within everyday life rather than intensive training.","explanation":"Người nói gợi ý đi bộ, đi thang bộ khi phù hợp hoặc giãn cơ trong giờ nghỉ học."},{"n":28,"stem":"Why may staying awake late and skipping meals be counterproductive?","options":{"A":"It guarantees that students will become ill.","B":"It can reduce their ability to study effectively.","C":"It makes all university assignments more difficult.","D":"It removes the need for counselling."},"answer":"B","evidence":"this approach can make it harder to study effectively.","explanation_en":"The speaker warns that apparent time-saving habits may undermine concentration and study performance.","explanation":"Người nói cho rằng thức khuya và bỏ bữa tưởng tiết kiệm thời gian nhưng có thể khiến việc học kém hiệu quả."},{"n":29,"stem":"What is the speaker’s attitude toward seeking mental-health support?","options":{"A":"Support-seeking is responsible and should not be stigmatised.","B":"Only students with severe illness should ask for help.","C":"Healthy routines always replace professional treatment.","D":"Universities should leave all stress management to students."},"answer":"A","evidence":"seeking support is a responsible decision, not a weakness.","explanation_en":"The lecturer supports confidential counselling and rejects the idea that asking for help is a weakness.","explanation":"Người nói ủng hộ tìm kiếm hỗ trợ tâm lý và bác bỏ quan niệm rằng nhờ giúp đỡ là yếu đuối."},{"n":30,"stem":"What does the example of the student group illustrate?","options":{"A":"Peer support can guarantee a healthy lifestyle.","B":"Students should never exercise alone.","C":"All students need identical activity plans.","D":"Small, achievable changes may be easier to maintain."},"answer":"D","evidence":"the plan was easier to continue than a demanding programme they had attempted before.","explanation_en":"The group sustained walking breaks more easily than an ambitious programme, illustrating realistic goals.","explanation":"Nhóm duy trì được những lần đi bộ ngắn tốt hơn chương trình khó trước đó, cho thấy mục tiêu nhỏ dễ thực hiện lâu dài."}]},{"part":3,"first":31,"last":35,"title":"Talk 3 – Digital health information and responsible decisions","audio":"P3.3.mp3","script":[{"speaker":"Female lecturer","text":"Good morning. Today we will consider how digital tools can support personal health decisions. Mobile applications can record sleep, count daily steps and remind users about medical appointments. These functions may be useful, but they are not medical diagnoses."},{"speaker":"Lecturer","text":"Imagine searching online for the cause of a headache. A website may list possible conditions. The list cannot examine the patient, consider every symptom or replace professional judgement. Similarly, a short stress questionnaire may encourage reflection without determining whether someone has a mental illness."},{"speaker":"Lecturer","text":"Reliability varies. Some health applications explain how their measurements were developed and what they cannot show. Others make confident claims without supporting evidence. Before trusting a result, ask what was measured and whether the claim has been evaluated. A colourful chart is not proof of reliability."},{"speaker":"Lecturer","text":"Privacy matters too. Details about symptoms and treatment may be sensitive. Before providing such information, users should consider who can access it and whether the service explains how data will be used. A long privacy notice is not necessarily a clear one."},{"speaker":"Lecturer","text":"We should not dismiss useful technology, however. Appointment reminders may help people follow medical advice, and activity records can inform conversations with clinicians. These tools are most valuable when they help users ask better questions rather than make decisions on their behalf."},{"speaker":"Lecturer","text":"The key is balance. Use digital resources to organise information, but consult a qualified professional for diagnosis and treatment decisions. Technology should support informed discussion, not create false certainty."}],"questions":[{"n":31,"stem":"Which uses of mobile health applications does the lecturer mention?","options":{"A":"Replace consultations with qualified doctors","B":"Guarantee recovery from common illnesses","C":"Track sleep and steps, and remind users about appointments","D":"Prescribe medication without professional approval"},"answer":"C","evidence":"Mobile applications can record sleep, count daily steps and remind users about medical appointments.","explanation_en":"The opening of the talk identifies three practical functions: recording sleep, counting steps and reminding people of medical appointments. It does not say that applications diagnose, prescribe or guarantee recovery.","explanation":"Ngay phần mở đầu, người nói đề cập ba chức năng: ghi nhận giấc ngủ, đếm số bước đi và nhắc lịch hẹn khám. Bài nói không khẳng định ứng dụng có thể thay bác sĩ, kê đơn hoặc bảo đảm khỏi bệnh."},{"n":32,"stem":"What is one limitation of a website listing possible causes of a headache?","options":{"A":"It can never mention a serious condition.","B":"It cannot examine the patient or assess every symptom.","C":"It must charge users before showing information.","D":"It records a medical prescription automatically."},"answer":"B","evidence":"The list cannot examine the patient, consider every symptom or replace professional judgement.","explanation_en":"A list of possible causes is not a personalised examination or diagnosis.","explanation":"Danh sách nguyên nhân trên website không thể khám bệnh nhân hoặc đánh giá đủ mọi triệu chứng, nên không phải chẩn đoán cá nhân hóa."},{"n":33,"stem":"What does the example of “a colourful chart” illustrate?","options":{"A":"To explain how doctors record prescriptions","B":"To show that visual design always improves accuracy","C":"To warn that attractive presentation does not establish reliability","D":"To recommend a particular health application"},"answer":"C","evidence":"A colourful chart is not proof of reliability.","explanation_en":"The example illustrates that appearance alone cannot validate a digital health claim.","explanation":"Hình biểu đồ đẹp mắt không chứng minh thông tin đáng tin cậy; dẫn chứng nhằm nhắc người dùng đánh giá căn cứ khoa học."},{"n":34,"stem":"What privacy question should users consider before entering health information?","options":{"A":"Who can access the data and how it will be used","B":"How many colours the application can display","C":"Whether all users have the same phone model","D":"How quickly the application opens each screen"},"answer":"A","evidence":"users should consider who can access it and whether the service explains how data will be used.","explanation_en":"The concern is data access and handling, not appearance or device features.","explanation":"Người dùng cần biết ai có quyền truy cập dữ liệu sức khỏe và dữ liệu sẽ được sử dụng như thế nào."},{"n":35,"stem":"Which statement best reflects the lecturer’s final recommendation?","options":{"A":"Avoid every digital tool whenever medical care is available.","B":"Use online questionnaires as definitive mental-health diagnoses.","C":"Choose digital services mainly because they provide quick results.","D":"Use digital tools to support informed discussions while seeking professional decisions for diagnosis and treatment."},"answer":"D","evidence":"Use digital resources to organise information, but consult a qualified professional for diagnosis and treatment decisions.","explanation_en":"The conclusion is balanced: technology supports information gathering, while diagnosis and treatment require professionals.","explanation":"Kết luận khuyến nghị dùng công cụ số để hỗ trợ thu thập thông tin và trao đổi, còn quyết định chẩn đoán, điều trị cần chuyên gia y tế."}]}],"warmup":{"listening":{"1":[{"n":1,"stem":"I need to make an _____ with the doctor for next Tuesday.","options":{"A":"appointment","B":"injury","C":"outbreak","D":"injection"},"answer":"A","translation":"Tôi cần đặt lịch hẹn với bác sĩ vào thứ Ba tuần tới."},{"n":2,"stem":"The nurse checked his _____ before allowing him to go home.","options":{"A":"balanced diet","B":"blood pressure","C":"mental health","D":"sleep quality"},"answer":"B","translation":"Y tá đo huyết áp của anh ấy trước khi cho anh về nhà."},{"n":3,"stem":"A high _____ can be a sign that your body is fighting an infection.","options":{"A":"appointment","B":"exercise","C":"fever","D":"recovery"},"answer":"C","translation":"Sốt cao có thể là dấu hiệu cơ thể đang chống lại sự nhiễm trùng."},{"n":4,"stem":"The doctor asked the patient to describe every _____.","options":{"A":"appointment","B":"hospital","C":"exercise","D":"symptom"},"answer":"D","translation":"Bác sĩ yêu cầu bệnh nhân mô tả từng triệu chứng."},{"n":5,"stem":"If your symptoms continue, you should _____ rather than ignoring them.","options":{"A":"see a doctor","B":"take a holiday","C":"miss a lecture","D":"buy a uniform"},"answer":"A","translation":"Nếu các triệu chứng kéo dài, bạn nên đi khám bác sĩ thay vì bỏ qua."},{"n":6,"stem":"She _____ after several days of rest and proper care.","options":{"A":"caught a train","B":"recovered from the flu","C":"made an appointment","D":"developed a rash"},"answer":"B","translation":"Cô ấy đã hồi phục sau cúm nhờ nghỉ ngơi và chăm sóc đúng cách."},{"n":7,"stem":"The clinic has started a free _____ for adults over forty.","options":{"A":"payment system","B":"driving lesson","C":"check-up programme","D":"language contest"},"answer":"C","translation":"Phòng khám triển khai chương trình khám sức khỏe miễn phí cho người trên bốn mươi tuổi."},{"n":8,"stem":"People who have a peanut allergy must _____ food labels carefully.","options":{"A":"repair","B":"forget","C":"design","D":"read"},"answer":"D","translation":"Người bị dị ứng đậu phộng phải đọc nhãn thực phẩm cẩn thận."},{"n":9,"stem":"Please _____ exactly as directed on the label.","options":{"A":"take the medicine","B":"make the weather","C":"break a record","D":"write a report"},"answer":"A","translation":"Vui lòng uống thuốc đúng theo hướng dẫn trên nhãn."},{"n":10,"stem":"The cyclist suffered a minor knee _____ after the fall.","options":{"A":"appointment","B":"injury","C":"diet","D":"vaccine"},"answer":"B","translation":"Người đi xe đạp bị chấn thương nhẹ ở đầu gối sau cú ngã."},{"n":11,"stem":"To stay _____, try to balance sleep, food and physical activity.","options":{"A":"infectious","B":"sedentary","C":"healthy","D":"incurable"},"answer":"C","translation":"Để giữ sức khỏe, hãy cố gắng cân bằng giấc ngủ, ăn uống và vận động."},{"n":12,"stem":"He had to _____ when his fever became worse overnight.","options":{"A":"go shopping","B":"go on holiday","C":"go to a concert","D":"go to hospital"},"answer":"D","translation":"Anh ấy phải đến bệnh viện khi cơn sốt nặng hơn trong đêm."},{"n":13,"stem":"During the winter, some students _____ and miss classes.","options":{"A":"catch the flu","B":"boost their budget","C":"break a promise","D":"pay a fine"},"answer":"A","translation":"Vào mùa đông, một số sinh viên bị cúm và nghỉ học."},{"n":14,"stem":"The nurse put a clean bandage on the _____ before it was examined.","options":{"A":"prescription","B":"wound","C":"appointment","D":"lifestyle"},"answer":"B","translation":"Y tá băng vết thương sạch trước khi vết thương được khám."},{"n":15,"stem":"A _____ includes fruit, vegetables and a variety of nutritious foods.","options":{"A":"medical operation","B":"sick leave","C":"balanced diet","D":"diagnosis"},"answer":"C","translation":"Chế độ ăn cân bằng gồm trái cây, rau và nhiều loại thực phẩm bổ dưỡng."},{"n":16,"stem":"He was advised to _____ every night before a long day of classes.","options":{"A":"avoid all rest","B":"skip every meal","C":"ignore fatigue","D":"get enough sleep"},"answer":"D","translation":"Anh ấy được khuyên nên ngủ đủ giấc mỗi tối trước ngày học dài."},{"n":17,"stem":"The medical team monitors each _____ closely after surgery.","options":{"A":"patient","B":"proposal","C":"discount","D":"receipt"},"answer":"A","translation":"Đội ngũ y tế theo dõi sát từng bệnh nhân sau phẫu thuật."},{"n":18,"stem":"She drank water frequently to _____ during the outdoor activity.","options":{"A":"suffer from stress","B":"stay hydrated","C":"lose her balance","D":"cancel the event"},"answer":"B","translation":"Cô ấy thường xuyên uống nước để cơ thể đủ nước trong hoạt động ngoài trời."}],"2":[{"n":1,"stem":"A _____ means sitting or lying down for most of the day.","options":{"A":"balanced meal","B":"medical breakthrough","C":"treatment plan","D":"sedentary lifestyle"},"answer":"D","translation":"Lối sống ít vận động có nghĩa là ngồi hoặc nằm phần lớn thời gian trong ngày."},{"n":2,"stem":"The coach asked Minh to _____ on sugary drinks gradually.","options":{"A":"cut down","B":"break out","C":"pass away","D":"come round"},"answer":"A","translation":"Huấn luyện viên yêu cầu Minh dần giảm đồ uống có đường."},{"n":3,"stem":"He started to _____ stress during the examination period.","options":{"A":"get over","B":"suffer from","C":"pass out","D":"look after"},"answer":"B","translation":"Anh ấy bắt đầu chịu căng thẳng trong mùa thi."},{"n":4,"stem":"It is difficult to _____ when you regularly sleep only four hours.","options":{"A":"prescribe","B":"transmit","C":"concentrate","D":"vaccinate"},"answer":"C","translation":"Rất khó tập trung khi bạn thường xuyên chỉ ngủ bốn giờ."},{"n":5,"stem":"The physiotherapist designed an individual _____ after the knee operation.","options":{"A":"financial discount","B":"library membership","C":"travel itinerary","D":"rehabilitation plan"},"answer":"D","translation":"Chuyên viên vật lý trị liệu thiết kế kế hoạch phục hồi riêng sau ca mổ đầu gối."},{"n":6,"stem":"The medicine produced mild _____, including tiredness.","options":{"A":"side effects","B":"balanced diets","C":"check-ups","D":"appointments"},"answer":"A","translation":"Thuốc gây một số tác dụng phụ nhẹ, gồm mệt mỏi."},{"n":7,"stem":"Students should _____ medical advice before returning to sport.","options":{"A":"avoid","B":"follow","C":"forget","D":"rewrite"},"answer":"B","translation":"Sinh viên nên tuân thủ lời khuyên y tế trước khi quay lại chơi thể thao."},{"n":8,"stem":"The doctor will _____ her condition during the first twenty-four hours.","options":{"A":"cancel","B":"promote","C":"monitor","D":"publish"},"answer":"C","translation":"Bác sĩ sẽ theo dõi tình trạng của cô ấy trong hai mươi bốn giờ đầu."},{"n":9,"stem":"He was given a _____ for medicine that can only be obtained at a pharmacy.","options":{"A":"diagnosis","B":"rehabilitation","C":"vaccination","D":"prescription"},"answer":"D","translation":"Anh ấy được cấp đơn thuốc để lấy thuốc tại nhà thuốc."},{"n":10,"stem":"After the accident, the patient needed several months to _____.","options":{"A":"recover","B":"spread","C":"infect","D":"prescribe"},"answer":"A","translation":"Sau tai nạn, bệnh nhân cần vài tháng để hồi phục."},{"n":11,"stem":"The coach encourages students to _____ rather than change all their habits at once.","options":{"A":"train without rest","B":"start with small steps","C":"ignore every warning","D":"quit all hobbies"},"answer":"B","translation":"Huấn luyện viên khuyến khích sinh viên bắt đầu từ những bước nhỏ thay vì thay đổi mọi thói quen cùng lúc."},{"n":12,"stem":"She received professional support to improve her emotional _____.","options":{"A":"prescription","B":"outbreak","C":"well-being","D":"surgery"},"answer":"C","translation":"Cô ấy nhận được hỗ trợ chuyên môn để cải thiện sức khỏe tinh thần."},{"n":13,"stem":"A long-term plan needs to be _____ enough for students to follow.","options":{"A":"incurable","B":"contagious","C":"genetic","D":"realistic"},"answer":"D","translation":"Kế hoạch lâu dài phải đủ thực tế để sinh viên có thể làm theo."},{"n":14,"stem":"Regular breaks can help people _____ stress at work.","options":{"A":"manage","B":"transmit","C":"prescribe","D":"diagnose"},"answer":"A","translation":"Các khoảng nghỉ thường xuyên có thể giúp mọi người kiểm soát căng thẳng tại nơi làm việc."},{"n":15,"stem":"The hospital offers counselling to help staff maintain good _____.","options":{"A":"blood pressure","B":"mental health","C":"recovery time","D":"vaccination rate"},"answer":"B","translation":"Bệnh viện có tư vấn giúp nhân viên duy trì sức khỏe tinh thần tốt."},{"n":16,"stem":"He should not _____ the amount of medication without consulting a doctor.","options":{"A":"examine","B":"recover","C":"increase","D":"protect"},"answer":"C","translation":"Anh ấy không nên tăng lượng thuốc mà không hỏi ý kiến bác sĩ."},{"n":17,"stem":"She hopes to _____ fully from the operation before returning to work.","options":{"A":"transmit","B":"investigate","C":"prescribe","D":"recover"},"answer":"D","translation":"Cô ấy hy vọng hồi phục hoàn toàn sau ca mổ trước khi đi làm lại."},{"n":18,"stem":"The nurse suggested the patient _____ his symptoms in a daily diary.","options":{"A":"record","B":"ignore","C":"conceal","D":"misplace"},"answer":"A","translation":"Y tá gợi ý bệnh nhân ghi chép triệu chứng vào nhật ký mỗi ngày."}],"3":[{"n":1,"stem":"Washing hands is one of several _____ to reduce infection risks.","options":{"A":"shopping promotions","B":"travel arrangements","C":"preventive measures","D":"exercise injuries"},"answer":"C","translation":"Rửa tay là một trong những biện pháp phòng ngừa để giảm nguy cơ nhiễm bệnh."},{"n":2,"stem":"During an _____, health authorities may issue additional public guidance.","options":{"A":"appointment","B":"operation","C":"exercise","D":"outbreak"},"answer":"D","translation":"Khi dịch bệnh bùng phát, cơ quan y tế có thể đưa ra hướng dẫn bổ sung."},{"n":3,"stem":"Some infections can _____ through close contact.","options":{"A":"spread","B":"recover","C":"prescribe","D":"relax"},"answer":"A","translation":"Một số bệnh nhiễm trùng có thể lây lan qua tiếp xúc gần."},{"n":4,"stem":"After fainting, the athlete slowly began to _____.","options":{"A":"pass away","B":"come round","C":"give up","D":"break out"},"answer":"B","translation":"Sau khi ngất, vận động viên dần tỉnh lại."},{"n":5,"stem":"The body relies on the _____ to respond to many infections.","options":{"A":"payment system","B":"appointment system","C":"immune system","D":"transport system"},"answer":"C","translation":"Cơ thể dựa vào hệ miễn dịch để phản ứng với nhiều bệnh nhiễm trùng."},{"n":6,"stem":"Reliable health information must be based on scientific _____.","options":{"A":"advertising","B":"popularity","C":"appearance","D":"evidence"},"answer":"D","translation":"Thông tin sức khỏe đáng tin cậy phải dựa trên bằng chứng khoa học."},{"n":7,"stem":"The researcher will _____ the reason for the sudden rise in cases.","options":{"A":"investigate","B":"prescribe","C":"recover","D":"recycle"},"answer":"A","translation":"Nhà nghiên cứu sẽ điều tra nguyên nhân số ca tăng đột ngột."},{"n":8,"stem":"Not every website can offer an accurate medical _____.","options":{"A":"discount","B":"diagnosis","C":"shipment","D":"reservation"},"answer":"B","translation":"Không phải website nào cũng có thể đưa ra chẩn đoán y khoa chính xác."},{"n":9,"stem":"Before sharing medical details, users should review the platform’s _____ policy.","options":{"A":"shipping","B":"refund","C":"privacy","D":"attendance"},"answer":"C","translation":"Trước khi chia sẻ thông tin y tế, người dùng nên xem chính sách quyền riêng tư của nền tảng."},{"n":10,"stem":"Doctors evaluate symptoms before recommending a suitable _____.","options":{"A":"application","B":"advertisement","C":"payment","D":"treatment"},"answer":"D","translation":"Bác sĩ đánh giá triệu chứng trước khi đề xuất phương pháp điều trị phù hợp."},{"n":11,"stem":"The painkiller started to _____ after several hours.","options":{"A":"wear off","B":"break out","C":"pass away","D":"come round"},"answer":"A","translation":"Thuốc giảm đau bắt đầu hết tác dụng sau vài giờ."},{"n":12,"stem":"The patient was relieved when she began to _____ to treatment.","options":{"A":"pass out","B":"respond well","C":"put on weight","D":"take sick leave"},"answer":"B","translation":"Bệnh nhân nhẹ nhõm khi bắt đầu đáp ứng tốt với điều trị."},{"n":13,"stem":"A health app may give useful reminders, but it cannot replace professional _____.","options":{"A":"retail pricing","B":"delivery policy","C":"judgement","D":"attendance"},"answer":"C","translation":"Ứng dụng sức khỏe có thể nhắc việc hữu ích nhưng không thể thay thế đánh giá chuyên môn."},{"n":14,"stem":"Vaccination and hygiene can help prevent the _____ of disease.","options":{"A":"weight","B":"treatment","C":"operation","D":"spread"},"answer":"D","translation":"Tiêm chủng và vệ sinh có thể giúp ngăn chặn sự lây lan của bệnh."},{"n":15,"stem":"She chose to _____ smoking after discussing long-term health risks.","options":{"A":"give up","B":"break out","C":"come down with","D":"pull through"},"answer":"A","translation":"Cô ấy quyết định bỏ hút thuốc sau khi tìm hiểu nguy cơ lâu dài."},{"n":16,"stem":"Digital health services should explain who can _____ sensitive user data.","options":{"A":"recover","B":"access","C":"transmit","D":"vaccinate"},"answer":"B","translation":"Dịch vụ sức khỏe số cần giải thích ai có quyền truy cập dữ liệu người dùng nhạy cảm."},{"n":17,"stem":"People with chronic conditions need guidance on how to _____ symptoms.","options":{"A":"purchase","B":"design","C":"manage","D":"advertise"},"answer":"C","translation":"Người mắc bệnh mạn tính cần hướng dẫn cách kiểm soát triệu chứng."},{"n":18,"stem":"A clear warning should not _____ people unnecessarily.","options":{"A":"vaccinate","B":"rehabilitate","C":"diagnose","D":"alarm"},"answer":"D","translation":"Cảnh báo rõ ràng không nên làm mọi người lo lắng không cần thiết."}]}},"glossary":{"health":{"appointment":"cuộc hẹn khám","balanced diet":"chế độ ăn cân bằng","blood pressure":"huyết áp","disease":"bệnh tật","exercise":"tập thể dục","fever":"sốt","flu":"cúm","headache":"đau đầu","healthy":"khỏe mạnh","hospital":"bệnh viện","illness":"bệnh, ốm đau","injury":"vết thương, chấn thương","medicine":"thuốc","nurse":"y tá","patient":"bệnh nhân","recovery":"sự hồi phục","symptom":"triệu chứng","treatment":"điều trị","vaccination":"tiêm chủng","virus":"vi-rút","make an appointment":"đặt lịch hẹn khám","catch a cold / flu":"bị cảm / cúm","take medicine":"uống thuốc","have a fever":"bị sốt","suffer from (an illness)":"bị mắc bệnh gì đó","go to hospital":"đến bệnh viện","be in good / bad health":"có sức khoẻ tốt / xấu","recover from (an illness)":"hồi phục sau bệnh","get better / worse":"trở nên tốt hơn / xấu hơn (về sức khoẻ)","follow a healthy lifestyle":"sống lành mạnh","have a balanced diet":"có chế độ ăn cân bằng","do regular exercise":"tập thể dục thường xuyên","stay hydrated":"giữ cho cơ thể đủ nước","get enough sleep":"ngủ đủ giấc","see a doctor":"đi khám bác sĩ","have a check-up":"đi khám sức khỏe định kỳ","be allergic to sth":"bị dị ứng với cái gì","avoid junk food":"tránh đồ ăn vặt có hại","suffer from stress":"bị căng thẳng","take a day off / take sick leave":"nghỉ một ngày vì ốm","addiction":"sự nghiện","allergy":"dị ứng","diagnosis":"sự chẩn đoán","examine":"kiểm tra, khám (bệnh)","genetic disorder":"rối loạn di truyền","immune system":"hệ miễn dịch","incurable":"không thể chữa khỏi","infection":"sự nhiễm trùng","investigate":"điều tra","mental illness":"bệnh tâm thần","obesity":"béo phì","operation":"ca phẫu thuật","outbreak":"sự bùng phát (dịch bệnh)","prescription":"đơn thuốc","preventive measures":"các biện pháp phòng ngừa","rehabilitation":"sự phục hồi, sự hồi phục","sedentary lifestyle":"lối sống ít vận động","side effects":"tác dụng phụ","stress-related":"liên quan đến căng thẳng","surgery":"ca phẫu thuật","therapeutic":"mang tính trị liệu","transmit":"truyền (bệnh)","well-being":"tình trạng khỏe mạnh","break out":"bắt đầu bất ngờ (đối với dịch bệnh, chiến tranh, cháy ...)","bring on":"gây ra (bệnh tật ...)","check up on":"kiểm tra sức khoẻ","come down with":"bắt đầu bị bệnh nhẹ","come round / to":"tỉnh lại, hồi tỉnh","come through":"vượt qua, bình phục","cut down (on)":"giảm bớt, cắt giảm","feel up to":"cảm thấy đủ sức để làm gì","fight off":"chống lại, đẩy lùi (bệnh tật)","get over":"hồi phục","give up":"từ bỏ","look after":"chăm sóc","pass away":"qua đời (nói theo cách tế nhị, lịch sự)","pass out":"ngất xỉu","pull through":"qua khỏi (bệnh nặng, tai nạn ...)","put down":"giết nhân đạo (thú bị bệnh nặng)","put on":"tăng cân","slow down":"giảm tốc độ, chậm lại (để nghỉ ngơi, hồi phục)","throw up":"nôn mửa","wear off":"hết tác dụng (thuốc ...)","alternative medicine / therapy":"phương pháp điều trị thay thế","break / cancel an appointment":"huỷ cuộc hẹn","in danger / out of danger":"trong tình trạng nguy hiểm / thoát khỏi nguy hiểm","take (some) exercise":"tập thể dục","stay / keep in shape":"giữ dáng","do sb good":"có lợi cho ai","have poor health / be in poor health":"có sức khỏe yếu","give sb an injection":"tiêm cho ai đó","study medicine":"học ngành y","boost the immune system":"tăng cường hệ miễn dịch","spread to a place":"lan ra một nơi nào đó","recover from an illness":"hồi phục sau khi ốm","have regular check-ups":"khám sức khỏe định kỳ","maintain good mental health":"duy trì sức khỏe tinh thần","develop symptoms":"bắt đầu xuất hiện triệu chứng","undergo surgery":"trải qua ca phẫu thuật","monitor one's condition":"theo dõi tình trạng sức khỏe","respond well to treatment":"đáp ứng tốt với điều trị","be diagnosed with sth":"được chẩn đoán mắc bệnh gì đó","manage a condition":"kiểm soát bệnh lý","prevent the spread of disease":"ngăn chặn sự lây lan của dịch bệnh","improve quality of life":"cải thiện chất lượng cuộc sống","follow medical advice":"tuân theo chỉ dẫn y tế","schedule":"lịch trình","physiotherapy":"vật lý trị liệu","evidence":"bằng chứng","medical":"thuộc y tế","immune":"miễn dịch","privacy":"quyền riêng tư","doctor":"bác sĩ","health":"sức khỏe","support":"hỗ trợ","student":"sinh viên","students":"sinh viên","blood":"máu","pressure":"áp lực; huyết áp (blood pressure)","vaccine":"vắc-xin","stress":"căng thẳng","care":"chăm sóc","consult":"tham khảo; tư vấn","accurate":"chính xác","confidential":"bảo mật","symptoms":"triệu chứng","mental":"tinh thần"}}};
